xpath.script:
console.groupCollapsed("[ronix_quality_manager.vapi] direct widget");
console.log("page", window.location.href);
console.log("requestPath", '');
console.log("routeCandidates", ['',]);
console.log("matchedButtonId", );
console.log("matchedButtonRoute", '');
console.log("mode", '');
console.log("topOffsetPx", );
console.log("rightOffsetPx", );
console.log("iconColor", '');
console.log("vapiEnabled", );
console.groupEnd();

t.script:
(function () {
    const widgetId = "ronix-quality-vapi-widget";
    let mutationLogCount = 0;

    function forcePosition(element, topPx, rightPx) {
        if (!element || element.nodeType !== 1) {
            return false;
        }
        element.style.setProperty("position", "fixed", "important");
        element.style.setProperty("top", topPx + "px", "important");
        element.style.setProperty("right", rightPx + "px", "important");
        element.style.setProperty("bottom", "auto", "important");
        element.style.setProperty("left", "auto", "important");
        element.style.setProperty("z-index", "1101", "important");
        return true;
    }

    function decorateLauncherIcon(element, iconColor) {
        if (!element || element.nodeType !== 1) {
            return false;
        }
        const existingIcon = element.querySelector("i.fa.fa-comments");
        if (existingIcon) {
            existingIcon.style.color = iconColor;
            const existingWrapper = existingIcon.parentElement;
            if (existingWrapper) {
                existingWrapper.style.color = iconColor;
            }
            element.dataset.ronixQualityVapiIconReady = "1";
            return true;
        }
        const svg = element.querySelector("svg");
        if (!svg) {
            return false;
        }
        const iconWrapper = svg.parentElement;
        if (!iconWrapper) {
            return false;
        }
        iconWrapper.innerHTML = '';
        iconWrapper.style.display = "flex";
        iconWrapper.style.alignItems = "center";
        iconWrapper.style.justifyContent = "center";
        iconWrapper.style.width = "28px";
        iconWrapper.style.height = "28px";
        iconWrapper.style.color = iconColor;
        element.dataset.ronixQualityVapiIconReady = "1";
        return true;
    }

    function isLauncherCandidate(element) {
        if (!element || element.nodeType !== 1) {
            return false;
        }
        const computed = window.getComputedStyle(element);
        const rect = element.getBoundingClientRect();
        const inlineStyle = (element.getAttribute("style") || "").toLowerCase();
        const text = (element.textContent || "").trim();
        return computed.position === "fixed" &&
            rect.width > 0 &&
            rect.height > 0 &&
            rect.width <= 420 &&
            rect.height <= 120 &&
            (
                inlineStyle.includes("top:") ||
                inlineStyle.includes("right:") ||
                inlineStyle.includes("cursor: pointer") ||
                text.includes("Rama Ai") ||
                text.includes("Call AI")
            );
    }

    function summarizeElement(element, label) {
        if (!element || element.nodeType !== 1) {
            return {label: label, exists: false};
        }
        const computed = window.getComputedStyle(element);
        const rect = element.getBoundingClientRect();
        return {
            label: label,
            exists: true,
            tagName: element.tagName,
            id: element.id || "",
            className: String(element.className || ""),
            ariaLabel: element.getAttribute("aria-label") || "",
            style: element.getAttribute("style") || "",
            dataset: Object.assign({}, element.dataset || {}),
            rect: {
                top: Math.round(rect.top),
                right: Math.round(rect.right),
                bottom: Math.round(rect.bottom),
                left: Math.round(rect.left),
                width: Math.round(rect.width),
                height: Math.round(rect.height),
            },
            computed: {
                position: computed.position,
                top: computed.top,
                right: computed.right,
                bottom: computed.bottom,
                left: computed.left,
                zIndex: computed.zIndex,
                display: computed.display,
                visibility: computed.visibility,
                opacity: computed.opacity,
            },
        };
    }

    function getCandidateElements(widget) {
        const candidates = new Set();
        if (widget.shadowRoot) {
            widget.shadowRoot.querySelectorAll(".vapi-btn, [class*='vapi'], button, [role='button']").forEach((element) => candidates.add(element));
        }
        widget.querySelectorAll("*").forEach((element) => {
            if (isLauncherCandidate(element)) {
                candidates.add(element);
            }
        });
        document.querySelectorAll("body > .vapi-btn, body > [class*='vapi'], body > button, body > div, body > aside").forEach((element) => {
            if (isLauncherCandidate(element)) {
                candidates.add(element);
            }
        });
        return Array.from(candidates);
    }

    function logWidgetDiagnostics(reason) {
        const widget = document.getElementById(widgetId);
        if (!widget) {
            console.warn("[ronix_quality_manager.vapi] widget element not found", {reason: reason});
            return;
        }
        const topPx = parseInt(widget.dataset.topOffsetPx || "88", 10);
        const rightPx = parseInt(widget.dataset.rightOffsetPx || "24", 10);
        const iconColor = widget.dataset.iconColor || "#F8FAFC";

        const candidates = getCandidateElements(widget);
        const candidateSummaries = candidates.map((element, index) => summarizeElement(element, "candidate-" + index));
        const shadowChildren = widget.shadowRoot
            ? Array.from(widget.shadowRoot.children).map((element, index) => summarizeElement(element, "shadow-child-" + index))
            : [];

        let appliedCount = 0;
        candidates.forEach((element) => {
            if (forcePosition(element, topPx, rightPx)) {
                appliedCount += 1;
            }
            decorateLauncherIcon(element, iconColor);
        });

        console.groupCollapsed("[ronix_quality_manager.vapi] offset sync");
        console.log("reason", reason);
        console.log("targetOffsets", {
            topPx: topPx,
            rightPx: rightPx,
            appliedCount: appliedCount,
            hasShadowRoot: Boolean(widget.shadowRoot),
            customElementDefined: Boolean(window.customElements && window.customElements.get && window.customElements.get("vapi-widget")),
        });
        console.log("widgetHostBeforeAfter", summarizeElement(widget, "widget-host"));
        console.log("widgetOuterHTML", widget.outerHTML);
        console.log("shadowChildren", shadowChildren);
        console.log("candidates", candidateSummaries);
        console.log("bodyVapiNodes", Array.from(document.querySelectorAll("body [class*='vapi'], body vapi-widget")).map((element, index) => summarizeElement(element, "body-node-" + index)));
        console.groupEnd();
    }

    const scheduleApply = function (reason) {
        logWidgetDiagnostics(reason + ":immediate");
        window.setTimeout(function () {
            logWidgetDiagnostics(reason + ":250ms");
        }, 250);
        window.setTimeout(function () {
            logWidgetDiagnostics(reason + ":1000ms");
        }, 1000);
    };

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", function () {
            scheduleApply("dom-content-loaded");
        }, {once: true});
    } else {
        scheduleApply("ready-state-complete");
    }

    if (window.customElements && window.customElements.whenDefined) {
        window.customElements.whenDefined("vapi-widget").then(function () {
            scheduleApply("custom-element-defined");
        });
    }

    const observer = new MutationObserver(function () {
        if (mutationLogCount < 5) {
            mutationLogCount += 1;
            logWidgetDiagnostics("mutation-" + mutationLogCount);
        }
    });

    const startObserver = function () {
        if (document.body) {
            observer.observe(document.body, {childList: true, subtree: true});
        }
    };

    if (document.body) {
        startObserver();
    } else {
        document.addEventListener("DOMContentLoaded", startObserver, {once: true});
    }
})();
